let durableState=structuredClone(state);
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));durableState=structuredClone(state);pulseSaved();return true;}catch{state=structuredClone(durableState);applyPrefs();notify('storageError',false);return false;}}
