function notify(key,success=true,{userTriggered=true}={}){recordOutcome(key);const el=document.querySelector('#notice');el.replaceChildren();if(state.prefs.emojis){const decoration=document.createElement('span');decoration.setAttribute('aria-hidden','true');decoration.textContent=success?'✅ ':'⚠️ ';el.append(decoration);}el.append(document.createTextNode(word(message(key,state.prefs))));el.classList.add('visible');clearTimeout(noticeTimer);const dismiss=document.createElement('button');dismiss.type='button';dismiss.className='dismiss-notice';dismiss.textContent=t('dismissNotice');dismiss.onclick=()=>el.classList.remove('visible');if(success&&UNDOABLE_OUTCOMES.has(key)&&state.history.length){const undo=document.createElement('button');undo.type='button';undo.className='notice-action';undo.textContent=t('undo');undo.onclick=()=>{el.classList.remove('visible');actions.undo();};el.append(undo);}el.append(dismiss);if(success)noticeTimer=setTimeout(()=>el.classList.remove('visible'),6000);speak(key,!success);if(userTriggered&&OUTCOME_EVENTS.has(key))playActionCue(!success?'refused':['taskDeleted','bulkDeleted'].includes(key)?'delete':'success');}
let soundStatus={played:false,reason:'idle'};
const soundPlayer=createSoundPlayer({getPreferences:()=>state.prefs,onStatus:status=>{soundStatus=status;updateSoundStatus();}});
function isSoundPreference(key){return Object.hasOwn(SOUND_DEFAULTS,key)||key==='reducedSound'||key==='quietHours';}
function soundStatusText(){
  if(!state.prefs.soundEffects)return t('soundDisabled');
  if(state.prefs.soundMuted)return t('soundMutedStatus');
  if(state.prefs.reducedSound||state.prefs.quietHours)return t('soundQuiet');
  if(state.prefs.soundVolume===0)return t('soundZero');
  if(soundStatus.reason==='idle'&&typeof globalThis.AudioContext!=='function'&&typeof globalThis.webkitAudioContext!=='function')return t('soundUnavailable');
  const key={scheduled:'soundScheduled',unavailable:'soundUnavailable','audio-refused':'soundRefused',suspended:'soundRefused','preferences-unavailable':'soundRefused',busy:'soundThrottled',cooldown:'soundThrottled',cancelled:'soundStopped',destroyed:'soundStopped'}[soundStatus.reason];
  return t(key||'soundReady');
}
function updateSoundStatus(){const output=document.querySelector('#sound-status');if(output)output.textContent=soundStatusText();}
function stopActionSounds(){soundPlayer.stop();soundStatus={played:false,reason:'cancelled'};updateSoundStatus();}
