window.addEventListener('pagehide',()=>soundPlayer.destroy(),{once:true});
let narrationStatus={type:'idle'};
const narrator=createNarrator({getPreferences:()=>state.prefs,onStatus:status=>{narrationStatus=status;updateNarrationStatus(status);}});
