function narrationStatusText(status=narrationStatus){if(!state.prefs.narration)return t('narrationOff');if(state.prefs.screenReaderActive||state.prefs.reducedSound||state.prefs.quietHours)return t('narrationSuppressed');if(status.type==='error')return t('narrationFailed');if(status.reason==='unavailable')return t('narrationUnavailable');if(status.reason==='no-voice')return t('noVoice');if(status.reason==='network-offline')return t('networkVoiceOffline');return t({speaking:'narrationSpeaking',ended:'narrationFinished',cancelled:'narrationStopped'}[status.type]||'narrationReady');}
function updateNarrationStatus(status){const el=document.querySelector('#narration-status');if(el)el.textContent=narrationStatusText(status);}
function applyPrefs(){document.documentElement.dataset.theme=effectiveTheme();document.documentElement.style.fontSize=state.prefs.scale+'%';document.documentElement.classList.toggle('reduce-motion',state.prefs.motion);document.documentElement.lang=state.prefs.language==='yue'?'yue-Hant':'en';}
// Motion layer. Every helper is optional decoration: when reduced motion is requested (by the
// operating system or by the app's own Reduce motion preference) or an API is missing, the
// final state is applied directly and nothing animates.
const UNDOABLE_OUTCOMES=new Set(['taskSaved','taskDeleted','bulkMoved','bulkDeleted','importDone']);
function motionAllowed(){try{return !state.prefs.motion&&!globalThis.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches;}catch{return false;}}
function motionToken(name,fallback){try{const value=getComputedStyle(document.documentElement).getPropertyValue(name).trim();const match=/^(\d+)ms\s+(.+)$/s.exec(value);if(match)return {duration:Number(match[1]),easing:match[2]};}catch{}return fallback;}
function animateSafe(element,frames,timing){if(typeof element?.animate!=='function')return null;try{return element.animate(frames,timing);}catch{try{return element.animate(frames,{...timing,easing:'cubic-bezier(0.2,0,0,1)'});}catch{return null;}}}
// FLIP: record card rectangles and lane counts before a render, then invert and play after it.
function captureLayout(){if(!motionAllowed())return null;const cards=new Map(),counts=new Map();for(const card of document.querySelectorAll('.task-card[data-task-id]')){if(typeof card.getBoundingClientRect==='function')cards.set(card.dataset.taskId,card.getBoundingClientRect());}for(const lane of document.querySelectorAll('.lane[data-lane]'))counts.set(lane.dataset.lane,lane.dataset.count);return {cards,counts};}
function playLayout(before){
  if(!before||!motionAllowed())return;
  const spring=motionToken('--motion-spring-default-spatial',{duration:500,easing:'cubic-bezier(0.2,0,0,1)'});
  for(const card of document.querySelectorAll('.task-card[data-task-id]')){
    if(typeof card.getBoundingClientRect!=='function')continue;
    const old=before.cards.get(card.dataset.taskId);
    if(!old){if(before.cards.size)animateSafe(card,[{opacity:0,transform:'scale(0.92)'},{opacity:1,transform:'none'}],spring);continue;}
    const now=card.getBoundingClientRect(),dx=old.left-now.left,dy=old.top-now.top;
    if(Math.abs(dx)>0.5||Math.abs(dy)>0.5)animateSafe(card,[{transform:`translate(${dx}px,${dy}px)`},{transform:'none'}],spring);
  }
  for(const lane of document.querySelectorAll('.lane[data-lane]')){
    const old=before.counts.get(lane.dataset.lane);if(old===undefined||old===lane.dataset.count)continue;
    const count=lane.querySelector('.lane-count');if(!count)continue;
    count.dataset.old=old;count.classList.add(Number(lane.dataset.count)>Number(old)?'roll-up':'roll-down');
  }
}
// Navigation indicator: a temporary pill travels and stretches from the old item to the new one.
function navIndicatorRect(){const icon=document.querySelector('.nav-item[aria-current] .nav-icon');return typeof icon?.getBoundingClientRect==='function'?icon.getBoundingClientRect():null;}
function playNavIndicator(from){
  if(!from||!motionAllowed())return;
  const target=document.querySelector('.nav-item[aria-current] .nav-icon');if(typeof target?.getBoundingClientRect!=='function')return;
  const to=target.getBoundingClientRect();if(Math.abs(to.left-from.left)<1&&Math.abs(to.top-from.top)<1)return;
  const nav=target.closest('.nav');if(typeof nav?.getBoundingClientRect!=='function')return;const origin=nav.getBoundingClientRect();
  const ghost=document.createElement('span');ghost.className='nav-ghost';ghost.setAttribute('aria-hidden','true');nav.prepend(ghost);
  const box=r=>({left:(r.left-origin.left)+'px',top:(r.top-origin.top)+'px',width:r.width+'px',height:r.height+'px'});
  const left=Math.min(from.left,to.left),top=Math.min(from.top,to.top);
  const stretch={left:(left-origin.left)+'px',top:(top-origin.top)+'px',width:(Math.max(from.right,to.right)-left)+'px',height:(Math.max(from.bottom,to.bottom)-top)+'px',offset:0.45};
  target.classList.add('is-arriving');
  const animation=animateSafe(ghost,[box(from),stretch,box(to)],motionToken('--motion-spring-fast-spatial',{duration:350,easing:'cubic-bezier(0.2,0,0,1)'}));
  const done=()=>{ghost.remove();target.classList.remove('is-arriving');};
  if(animation?.finished)animation.finished.then(done,done);else done();
}
// Theme switch: circular reveal from the chosen tile with View Transitions, else a short fade.
function changeTheme(trigger,apply){
  const root=document.documentElement;
  if(!motionAllowed()||!root){apply();return;}
  if(typeof document.startViewTransition==='function'){
    try{const r=trigger.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2;root.style.setProperty('--reveal-x',x+'px');root.style.setProperty('--reveal-y',y+'px');root.style.setProperty('--reveal-r',Math.hypot(Math.max(x,innerWidth-x),Math.max(y,innerHeight-y))+'px');}catch{}
    root.classList.add('theme-reveal');
    try{const transition=document.startViewTransition(apply);transition.finished.finally(()=>root.classList.remove('theme-reveal'));return;}catch{root.classList.remove('theme-reveal');}
  }
  apply();root.classList.remove('theme-fade');void root.offsetWidth;root.classList.add('theme-fade');setTimeout(()=>root.classList.remove('theme-fade'),260);
}
// "Saved in this browser" chip pulses once after every successful save.
function pulseSaved(){Promise.resolve().then(()=>{for(const chip of document.querySelectorAll('.saved-chip')){if(!chip.classList)continue;chip.classList.remove('pulse');void chip.offsetWidth;chip.classList.add('pulse');}});}
function setModalOrigin(dialog,trigger){try{const from=trigger?.getBoundingClientRect?.(),box=dialog.getBoundingClientRect();if(from&&box.width&&(from.width||from.height))dialog.style.setProperty('--modal-origin',`${Math.round(from.left+from.width/2-box.left)}px ${Math.round(from.top+from.height/2-box.top)}px`);else dialog.style.removeProperty('--modal-origin');}catch{}}
function paintRange(input){if(!input?.style||input.type!=='range')return;const min=Number(input.min||0),max=Number(input.max||100),value=Number(input.value);const ratio=max>min?(value-min)/(max-min):0;input.style.setProperty('--fill',(Math.min(1,Math.max(0,ratio))*100).toFixed(2)+'%');}
function paintRanges(root){for(const input of root?.querySelectorAll?.('input[type=range]')||[])paintRange(input);}
const waveProgress=(value,max)=>(max?Math.min(100,Math.max(0,value/max*100)):0).toFixed(1)+'%';
function wavy(value,max,attributes=''){return `<div class="wavy" aria-hidden="true" ${attributes} style="--progress:${waveProgress(value,max)}"><span class="wavy-fill"></span><span class="wavy-track"></span></div>`;}
const icon=(name,extra='')=>`<span class="ms${extra?' '+extra:''}" aria-hidden="true">${name}</span>`;
const SEARCH_SCOPES=Object.freeze({tasks:'searchTasks',guide:'searchGuide',inventory:'searchInventory',settings:'searchSettings',palette:'searchPalette',history:'searchHistory',notifications:'searchNotifications'});
const searchInstances=new Map(),searchStates=new Map(),searchReady=new Map();
function destroySearchBuilders(owner){
  for(const [scope,entry] of searchInstances){if(!owner||owner.contains(entry.node)){searchStates.set(scope,entry.node.searchBuilder.getState());entry.node.searchBuilder.destroy();for(const event of ['input','change','click'])entry.node.removeEventListener(event,entry.clear);searchInstances.delete(scope);}}
}
function updateTaskFilterIndicator(){const summary=document.querySelector('.filter > summary');if(!summary)return;const active=!!searchInstances.get('tasks')?.node.searchBuilder.getState().query;summary.textContent=t('filter')+(state.prefs.focus?' · '+t('focus'):'')+(active?' · '+t('activeSearch'):'');}
function mountSearchBuilders(owner){
  if(!owner)return;
  for(const mount of owner.querySelectorAll('[data-search-mount]')){
    const scope=mount.dataset.searchMount;if(searchInstances.has(scope))continue;
    const items=()=>[...document.querySelectorAll(`[data-filter-scope="${scope}"]`)].map(element=>({element,text:element.dataset.filterText||element.textContent||''}));
    const node=createSearchBuilder({transformText:word,id:'workbench-'+scope,language:state.prefs.language,label:t(SEARCH_SCOPES[scope]||'search'),getItems:items,
      onStatus:status=>{if(status.state==='running'){searchReady.set(scope,false);if(scope==='tasks'){clearTaskSelection();updateTaskFilterIndicator();}}},
      onResults:(matches,report)=>{searchReady.set(scope,report.ok===true);const visible=new Set(matches.map(item=>item.element));for(const item of items())item.element.hidden=report.ok!==true||!visible.has(item.element);if(scope==='tasks')clearTaskSelection();const saved=searchInstances.get(scope)?.node.searchBuilder.getState();if(report.ok&&saved?.query)markGuide(saved.regex?'pattern':'searched');}
    });
    let lastFilter=JSON.stringify(node.searchBuilder.getState());
    const clear=()=>{const next=JSON.stringify(node.searchBuilder.getState());if(scope==='tasks'&&next!==lastFilter){searchReady.set(scope,false);clearTaskSelection();}lastFilter=next;if(scope==='tasks')updateTaskFilterIndicator();};
    node.addEventListener('input',clear);node.addEventListener('change',clear);node.addEventListener('click',clear);
    mount.append(node);searchInstances.set(scope,{node,clear});
    const previous=searchStates.get(scope);if(previous)node.searchBuilder.setQuery(previous.query,{regex:previous.regex,flags:previous.flags});if(scope==='tasks'){if(node.searchBuilder.getState().query){const disclosure=mount.closest?.('details.filter');if(disclosure)disclosure.open=true;}updateTaskFilterIndicator();}
  }
}
function searchBox(scope){return `<div class="search-box" data-search-mount="${scope}"></div>`;}
// Retained refresh entrypoint for existing callers; all matching stays in the component worker.
function search(scope){if(scope==='tasks')clearTaskSelection();searchInstances.get(scope)?.node.searchBuilder.refresh();}
