function openModal(html,label){const dialog=document.querySelector('#modal');destroySearchBuilders(dialog);schedulePanel=null;if(!dialog.open)modalReturn=document.activeElement;dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${state.prefs.emojis?'<span aria-hidden="true">🗂️ </span>':''}${esc(t(label))}</h2><button class="icon-button" data-action="close" aria-label="${esc(t('close'))}">${icon('close')}</button></div>${html}`;dialog.setAttribute('aria-labelledby','dialog-title');if(!dialog.open){dialog.showModal();setModalOrigin(dialog,modalReturn);}mountSearchBuilders(dialog);paintRanges(dialog);setTimeout(()=>(dialog.querySelector('input:not([type=checkbox]):not([type=range]):not([type=file])')||dialog.querySelector('button'))?.focus(),0);}
