function voiceOptions(lang,info=narrator.getVoices()[lang]){return `<option value="" ${!info.selectedId?'selected':''}>${esc(t('automatic'))}</option>${info.missing?`<option value="${esc(info.selectedId)}" selected>${esc(t('savedVoiceMissing'))}</option>`:''}${info.voices.map(v=>`<option value="${esc(v.id)}" ${info.selectedId===v.id?'selected':''}>${esc(v.name+' · '+v.lang+' · '+t(v.local?'localVoice':'networkVoice'))}</option>`).join('')}`;}
function voiceDescription(info){const parts=[];if(info.missing)parts.push(t('savedVoiceRetained'));if(info.reason)parts.push(t({'unavailable':'narrationUnavailable','no-voice':'noVoice','network-offline':'networkVoiceOffline'}[info.reason]||'narrationFailed'));if(info.effective)parts.push(t('effectiveVoice')+': '+info.effective.name+' ('+info.effective.lang+'). '+t(info.network?'networkVoice':'localVoice'));return parts.join(' ');}
function refreshNarrationUI(voices,status){if(status.type==='voices'){for(const lang of ['en','yue']){const select=document.querySelector('[data-voice-picker="'+lang+'"]');if(select){const options=voiceOptions(lang,voices[lang]);if(select.innerHTML!==options)select.innerHTML=options;select.value=voices[lang].selectedId;}const description=document.querySelector('#voice-status-'+lang);if(description)description.textContent=voiceDescription(voices[lang]);}const section=document.querySelector('#narration-status')?.closest('.pref-section');if(section)section.dataset.filterText=section.textContent;}updateNarrationStatus(status);}
narrator.subscribe(refreshNarrationUI);
