function narrationControls(){const voices=narrator.getVoices();return `<p>${esc(t('narratorNote'))}</p><label class="switch-line"><input type="checkbox" data-pref="narration" ${state.prefs.narration?'checked':''}>${esc(t('narrationOn'))}</label><fieldset><legend>${esc(t('narrationLanguage'))}</legend>${choices('narrationLanguage',[['en','english'],['yue','cantonese'],['both','bilingual']])}<p class="micro">${esc(t('narrationLanguageHelp'))}</p></fieldset>${['en','yue'].map(lang=>`<label class="field">${esc(t(lang==='en'?'voiceEn':'voiceYue'))}<select data-voice-picker="${lang}" data-pref="${lang==='en'?'voiceEn':'voiceYue'}" aria-describedby="voice-status-${lang}">${voiceOptions(lang,voices[lang])}</select></label><p class="voice-status" id="voice-status-${lang}">${esc(voiceDescription(voices[lang]))}</p>`).join('')}<p class="micro">${esc(t('speechHelp'))}</p>${[['speechRate','rate'],['speechPitch','pitch']].map(([key,range])=>`<label class="range-label">${esc(t(key))}<input type="range" min="${SPEECH_RANGES[range].min}" max="${SPEECH_RANGES[range].max}" step="0.1" data-pref="${key}" value="${state.prefs[key]}"><output>${state.prefs[key]}</output></label>`).join('')}${['screenReaderActive','reducedSound','quietHours'].map(key=>`<label class="switch-line"><input type="checkbox" data-pref="${key}" ${state.prefs[key]?'checked':''}>${esc(t(key))}</label>`).join('')}<p id="narration-status" class="narration-status" role="status" aria-live="polite">${esc(narrationStatusText())}</p><div class="wrap-actions"><button data-action="test-voice">${esc(t('testVoice'))}</button><button data-action="stop-voice">${esc(t('stopNarration'))}</button></div>`;}
