function settingCommandEnabled(command){return !command.requiresWords||Object.keys(vocabulary).length>0;}
function settingCommandLabel(command){return t(command.label)+(command.detail?' · '+t(command.detail):'');}
function decorateSettingsControls(){
  const dialog=document.querySelector('#modal'),described=new Set();
  for(const command of SETTING_COMMANDS){
    if(described.has(command.selector))continue;described.add(command.selector);
    const control=dialog.querySelector(command.selector);if(!control)continue;
    const descriptionId='setting-help-'+command.id;
    const hint=document.createElement('span');hint.id=descriptionId;hint.className='sr-only';hint.textContent=t(command.help);control.closest('.pref-section')?.append(hint);
    const existing=(control.getAttribute('aria-describedby')||'').split(/\s+/).filter(Boolean);control.setAttribute('aria-describedby',[...new Set([...existing,descriptionId])].join(' '));control.title=t(command.help);
    if(!control.matches('input,button,select,textarea'))control.tabIndex=-1;
  }
}
function focusSetting(id){
  const command=SETTING_COMMANDS.find(item=>item.id===id);if(!command||!settingCommandEnabled(command))return false;
  settings();const search=searchInstances.get('settings')?.node.searchBuilder;search?.setQuery('',{regex:false,flags:'i'});
  const control=document.querySelector('#modal').querySelector(command.selector);if(!control||control.disabled)return false;
  const section=control.closest('.pref-section');if(section)section.hidden=false;
  setTimeout(()=>{if(control.isConnected){control.focus({preventScroll:true});control.scrollIntoView({block:'center',behavior:'auto'});}},0);return true;
}
function settingsCommandRows(){return SETTING_COMMANDS.map(command=>{const label=t('settings')+' · '+settingCommandLabel(command),enabled=settingCommandEnabled(command),help=t(command.help),value=command.pref?String(state.prefs[command.pref]):'';return `<button data-setting-focus="${command.id}" data-filter-scope="palette" data-filter-text="${esc(label+' '+help+' '+value)}" ${enabled?'':'disabled'} title="${esc(help)}"><span>${esc(label)}${enabled?'':`<small>${esc(t('settingUnavailable'))}</small>`}</span><span aria-hidden="true">↗</span></button>`;}).join('');}

function settings(){openModal(`<div class="settings-layout"><nav class="pref-nav" aria-label="${esc(t('settingsSections'))}">${PREF_SECTIONS.map(([key,glyph])=>`<button type="button" class="pref-jump" data-pref-jump="${key}">${icon(glyph)}<span>${esc(t(key))}</span></button>`).join('')}</nav><div class="settings-body">${searchBox('settings')}<div class="preferences">${prefSection('displayName',`<p>${esc(t('displayNameHelp'))}</p><label class="field">${esc(t('displayName'))}<input id="display-name" value="${esc(state.prefs.displayName)}" maxlength="160" autocomplete="off"></label><button data-action="save-name">${esc(t('saveName'))}</button>`)}${prefSection('language',choices('language',[['en','english'],['yue','cantonese'],['both','bilingual']])+`<p>${esc(t('funNote'))}</p>${['funEn','funYue'].map(k=>`<label class="range-label">${esc(t(k))}<input type="range" min="1" max="5" data-pref="${k}" value="${state.prefs[k]}"><output>${state.prefs[k]}</output></label>`).join('')}<label class="switch-line"><input type="checkbox" data-pref="emojis" ${state.prefs.emojis?'checked':''}>${esc(t('emojis'))}</label>`)}${prefSection('appearance',choices('theme',[['light','light'],['dark','dark']])+`<label class="range-label">${esc(t('scale'))}<input type="range" min="85" max="150" step="5" data-pref="scale" value="${state.prefs.scale}"><output>${state.prefs.scale}%</output></label><label class="switch-line"><input type="checkbox" data-pref="motion" ${state.prefs.motion?'checked':''}>${esc(t('motion'))}</label>`)}${prefSection('words',`<p>${esc(t('wordsHelp'))}</p><p id="word-status">${Object.keys(vocabulary).length?esc(t('saved')):esc(t('wordsNone'))}</p><label class="file-label">${esc(t('load'))}<input type="file" accept=".json,application/json" data-word-upload></label><button data-action="clear-words" ${Object.keys(vocabulary).length?'':'disabled'}>${esc(t('clear'))}</button>`)}${prefSection('sounds',soundControls())}${prefSection('narrator',narrationControls())}${prefSection('data',`<p>${esc(t('backupNote'))}</p><p>${esc(t('backupScheduleNote'))}</p><div class="wrap-actions"><button data-action="schedules">${esc(t('schedules'))}</button><button data-action="export">${esc(t('export'))}</button><label class="file-label">${esc(t('import'))}<input type="file" accept=".json,application/json" data-import></label><button data-action="history">${esc(t('history'))}</button><button data-action="restart">${esc(t('resume'))}</button><button data-action="reset">${esc(t('reset'))}</button></div>`)}${prefSection('about',`<p>${esc(t('boundary'))}</p><p>${esc(t('material'))}</p>`)}</div></div></div>`,'settings');decorateSettingsControls();document.querySelectorAll('.pref-section').forEach(el=>el.dataset.filterText=el.textContent);}
function history(){openModal(`${searchBox('history')}<p class="micro">${esc(t('backupNote'))}</p><div class="history-list">${state.history.length?[...state.history].reverse().map((h,i)=>`<article style="--i:${Math.min(i,12)}" data-filter-scope="history" data-filter-text="${esc(h.label+' '+h.at)}"><div><strong>${esc(t(h.label))}</strong><small>${esc(new Date(h.at).toLocaleString())} · ${h.snapshot.tasks.length} ${esc(t('all'))}</small></div><button data-restore="${state.history.length-1-i}">${esc(t('restore'))}</button></article>`).join(''):`<p>${esc(t('noHistory'))}</p>`}</div>`,'history');}
const commands=[['new','add'],['settings','settings'],['history','history'],['notifications','notifications'],['schedules','schedules'],['export','export'],['guide','guide'],['tools','tools'],['workspace','workspace'],['restart','resume'],['word-focus','words']];
function palette(){markGuide('palette');openModal(`${searchBox('palette')}<div class="command-list">${commands.map(([a,k])=>`<button data-action="${a}" data-filter-scope="palette" data-filter-text="${esc(t(k))}"><span>${esc(t(k))}</span><span aria-hidden="true">↗</span></button>`).join('')}${settingsCommandRows()}</div>`,'palette');}
function doRestore(index){const h=state.history[index];if(!h)return;const data=validState(h.snapshot);snapshot('restore');state.tasks=data.tasks;stopActionSounds();narrator.cancel();state.prefs=data.prefs;if(persist()){closeModal();render();markGuide('recovered');notify('restored');}}
function exportData(){const value={...validState(state),omitted:['personal wording','file metadata']};const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='commonplace-workspace.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);markGuide('exported');notify('exportDone');}
async function importData(file){if(!file||file.size>2*1024*1024){notify('invalid',false);return;}try{const raw=parseBoundedJSON(new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer()),2*1024*1024);if(!raw||typeof raw!=='object'||Array.isArray(raw)||Object.keys(raw).some(k=>!['schemaVersion','tasks','prefs','omitted'].includes(k))||('omitted'in raw&&(!Array.isArray(raw.omitted)||raw.omitted.some(x=>typeof x!=='string'||x.length>100))))throw Error('invalid');const data=validState(raw);openModal(`<p>${esc(t('importDetails'))}</p><p>${data.tasks.length} ${esc(t('all'))}</p><div class="dialog-actions"><button data-action="close">${esc(t('cancel'))}</button><button class="primary" id="confirm-import">${esc(t('import'))}</button></div>`,'importConfirm');document.querySelector('#confirm-import').onclick=()=>{snapshot('import');state.tasks=data.tasks;stopActionSounds();narrator.cancel();state.prefs=data.prefs;state.setup.complete=true;if(persist()){closeModal();render();markGuide('imported');notify('importDone');}};}catch{notify('invalid',false);}}
async function importWords(file,dropped=false){
 if(!file||file.size>262144||!file.name.toLowerCase().endsWith('.json')){notify('invalid',false);return;}
 let validated;
 try{validated=parseVocabularyBytes(new Uint8Array(await file.arrayBuffer()));}catch{notify('invalid',false);return;}
 try{localStorage.setItem(WORDS,JSON.stringify(validated));}catch{notify('storageError',false);return;}
 vocabulary=validated.entries;render();if(document.querySelector('#modal').open)settings();
 if(dropped&&route!=='guide'){
  const el=document.createElement('div');el.className='celebration';el.setAttribute('role','status');
  el.textContent=vocabulary['private vocabulary']||t('wordApplied');document.body.append(el);setTimeout(()=>el.remove(),3000);
 }else notify('wordApplied');
}
const actions={schedules:openSchedules,'schedule-undo':undoSchedule,'schedule-export':exportSchedule,notifications,'save-name':saveDisplayName,'select-visible':()=>selectVisible(),'invert-visible':()=>selectVisible(true),'clear-selection':clearTaskSelection,new:()=>editor(),settings,palette,history,undo:()=>{const previous=state.history.pop();if(!previous)return;const data=validState(previous.snapshot);state.tasks=data.tasks;stopActionSounds();narrator.cancel();state.prefs=data.prefs;if(persist()){render();markGuide('recovered');notify('restored');}},export:exportData,data:settings,close:closeModal,guide:()=>{closeModal();location.hash='guide';},tools:()=>{closeModal();location.hash='tools';},workspace:()=>{closeModal();location.hash='workspace';},restart:()=>{state.setup.complete=false;state.setup.step=0;persist();closeModal();route='workspace';location.hash='workspace';render();},reset:()=>{stopActionSounds();narrator.cancel();state.prefs={...defaults};persist();render();settings();},'test-sound':()=>playActionCue('success'),'stop-sound':stopActionSounds,'test-voice':()=>speak('narrationTest'),'stop-voice':()=>narrator.cancel(),'word-focus':()=>{settings();setTimeout(()=>document.querySelector('[data-word-upload]')?.focus(),0);},'clear-words':()=>{try{localStorage.removeItem(WORDS);vocabulary={};render();settings();}catch{notify('storageError',false);}},'setup-back':()=>{state.setup.step=Math.max(0,state.setup.step-1);persist();render();},'setup-next':()=>{if(state.setup.step<2)state.setup.step++;else{if(state.setup.draft.trim()){if(state.tasks.length>=2000){notify('taskLimit',false);return;}snapshot('add');state.tasks.push({id:crypto.randomUUID(),title:state.setup.draft.trim(),notes:'',status:'todo'});}state.setup.complete=true;state.setup.draft='';}persist();render();}};
document.addEventListener('click',event=>{const target=event.target.closest('button,[data-action]');if(!target)return;if(target.dataset.settingFocus)focusSetting(target.dataset.settingFocus);if(target.dataset.bulkDestination)reviewBatch(target.dataset.bulkDestination);if(target.hasAttribute('data-bulk-delete'))reviewBatch(null);if(target.dataset.action)actions[target.dataset.action]?.();if(target.dataset.edit)editor(target.dataset.edit);if(target.dataset.delete){const id=target.dataset.delete;openModal(`<p>${esc(t('deleteBody'))}</p><div class="dialog-actions"><button data-edit="${esc(id)}">${esc(t('cancel'))}</button><button class="danger" id="confirm-delete">${esc(t('remove'))}</button></div>`,'confirmDelete');document.querySelector('#confirm-delete').onclick=()=>{snapshot('remove');state.tasks=state.tasks.filter(x=>x.id!==id);if(persist()){closeModal();render();notify('taskDeleted');}};}if(target.dataset.move){snapshot('edit');const task=state.tasks.find(x=>x.id===target.dataset.move);if(task){task.status=target.dataset.status;if(persist()){markGuide('moved');render();notify('taskSaved');}}}if(target.dataset.restore)doRestore(Number(target.dataset.restore));if(target.dataset.choice){const apply=()=>{if(isNarrationPreference(target.dataset.choice))narrator.cancel();state.prefs[target.dataset.choice]=target.dataset.value;if(persist()&&!isNarrationPreference(target.dataset.choice))markGuide(target.dataset.choice==='language'?'language':'appearance');if(isNarrationPreference(target.dataset.choice))narrator.refresh();render();if(document.querySelector('#modal').open)settings();};if(target.dataset.choice==='theme'&&target.dataset.value!==state.prefs.theme)changeTheme(target,apply);else apply();}if(target.dataset.prefJump){const section=document.querySelector('#pref-'+CSS.escape(target.dataset.prefJump));if(section){section.hidden=false;section.scrollIntoView({block:'start',behavior:motionAllowed()?'smooth':'auto'});section.querySelector('h3')?.focus({preventScroll:true});}}});
document.addEventListener('submit',event=>{if(event.target.id!=='task-form')return;event.preventDefault();const form=event.target,data=new FormData(form),title=data.get('title').trim();if(!title){form.elements.title.setCustomValidity(t('title'));form.elements.title.reportValidity();return;}if(!form.dataset.id&&state.tasks.length>=2000){notify('taskLimit',false);return;}const task={id:form.dataset.id||crypto.randomUUID(),title,notes:data.get('notes'),status:data.get('status')};snapshot(form.dataset.id?'edit':'add');const index=state.tasks.findIndex(x=>x.id===task.id);index<0?state.tasks.push(task):state.tasks[index]=task;if(persist()){markGuide(form.dataset.id?'edited':'created');closeModal();render();notify('taskSaved');}});
document.addEventListener('input',event=>{const el=event.target;if(el.name==='title')el.setCustomValidity('');if(el.id==='setup-task'){state.setup.draft=el.value;persist();}if(el.dataset.pref&&el.type==='range'){if(isSoundPreference(el.dataset.pref))stopActionSounds();if(isNarrationPreference(el.dataset.pref))narrator.cancel();state.prefs[el.dataset.pref]=Number(el.value);el.nextElementSibling.textContent=el.dataset.pref==='soundVolume'?Math.round(Number(el.value)*100)+'%':el.value+(el.dataset.pref==='scale'?'%':'');applyPrefs();if(persist()&&!isNarrationPreference(el.dataset.pref)&&!isSoundPreference(el.dataset.pref))markGuide(el.dataset.pref==='funEn'||el.dataset.pref==='funYue'?'tone':'appearance');if(isNarrationPreference(el.dataset.pref))narrator.refresh();if(isSoundPreference(el.dataset.pref))updateSoundStatus();}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.pref){if(isSoundPreference(el.dataset.pref))stopActionSounds();if(isNarrationPreference(el.dataset.pref))narrator.cancel();state.prefs[el.dataset.pref]=el.type==='checkbox'?el.checked:el.type==='range'?Number(el.value):el.value;applyPrefs();if(persist()&&['scale','motion','theme'].includes(el.dataset.pref))markGuide('appearance');if(isNarrationPreference(el.dataset.pref))narrator.refresh();if(isSoundPreference(el.dataset.pref))updateSoundStatus();if(el.dataset.pref==='focus')render();}if(el.hasAttribute('data-schedule-import'))importSchedule(el.files[0]);if(el.hasAttribute('data-import'))importData(el.files[0]);if(el.hasAttribute('data-word-upload'))importWords(el.files[0]);});
document.addEventListener('input',event=>paintRange(event.target));
